from __future__ import annotations

"""Decides which cache entries to drop when a resource is republished.

When a resource is activated, the rendered page at that path is stale, and so is
every cached page that embedded it. The job here is to gather that affected set
from the dependency index and evict exactly those entries from the cache, while
leaving pages that never touched the resource alone.
"""

from cache_invalidator_support import build_history_line, dedupe_keep_order
from dependency_index import DependencyIndex
from fragment_models import InvalidationResult, normalize_path
from page_cache import PageCache


def affected_paths(index: DependencyIndex, published_path: str) -> list[str]:
    """The published path plus the resources that embed it.

    The published path renders to a stale entry itself, and anything embedding
    it has stale HTML too, so all of them belong in the eviction set.
    """

    target = normalize_path(published_path)
    collected = [target]
    collected.extend(sorted(index.direct_dependents_of(target)))
    return dedupe_keep_order(collected)


def invalidate(
    cache: PageCache,
    index: DependencyIndex,
    published_path: str,
) -> InvalidationResult:
    """Evict the cache entries made stale by publishing ``published_path``."""

    target = normalize_path(published_path)
    candidates = affected_paths(index, target)

    evicted: list[str] = []
    history: list[str] = []
    for path in candidates:
        if cache.evict(path):
            evicted.append(path)
            history.append(build_history_line(target, path))

    return InvalidationResult(
        published_path=target,
        evicted_paths=tuple(evicted),
        examined_paths=tuple(candidates),
        history=history,
    )


def invalidate_many(
    cache: PageCache,
    index: DependencyIndex,
    published_paths,
) -> list[InvalidationResult]:
    results = []
    for path in published_paths:
        results.append(invalidate(cache, index, path))
    return results


def would_evict(index: DependencyIndex, published_path: str) -> set[str]:
    """Preview the eviction set without touching the cache."""

    return set(affected_paths(index, published_path))


def evicted_paths_for(
    cache: PageCache,
    index: DependencyIndex,
    published_path: str,
) -> set[str]:
    return set(invalidate(cache, index, published_path).evicted_paths)


def total_evicted(results) -> int:
    return sum(result.evicted_count() for result in results)

