from __future__ import annotations

"""Small helpers used while building and reporting an invalidation pass.

These are intentionally side-effect free: ordering, dedupe, and human-readable
log lines. They are split out so the invalidation routine reads as a flow rather
than a wall of string formatting and set bookkeeping.
"""

from fragment_models import normalize_path


def dedupe_keep_order(paths) -> list[str]:
    """Drop duplicates while preserving first-seen order."""

    seen: set[str] = set()
    ordered: list[str] = []
    for path in paths:
        key = normalize_path(path)
        if key in seen:
            continue
        seen.add(key)
        ordered.append(key)
    return ordered


def build_history_line(published_path: str, evicted_path: str) -> str:
    target = normalize_path(published_path)
    victim = normalize_path(evicted_path)
    if victim == target:
        return f"evict {victim} (republished)"
    return f"evict {victim} (embeds {target})"


def sort_paths(paths) -> list[str]:
    return sorted(normalize_path(p) for p in paths)


def union_paths(*groups) -> set[str]:
    merged: set[str] = set()
    for group in groups:
        for path in group:
            merged.add(normalize_path(path))
    return merged


def difference(left, right) -> set[str]:
    right_keys = {normalize_path(p) for p in right}
    return {normalize_path(p) for p in left if normalize_path(p) not in right_keys}


def partition_by(paths, predicate) -> tuple[list[str], list[str]]:
    matched: list[str] = []
    rest: list[str] = []
    for path in paths:
        if predicate(path):
            matched.append(path)
        else:
            rest.append(path)
    return matched, rest


def summarize_eviction(published_path: str, evicted, examined) -> dict[str, object]:
    evicted_list = dedupe_keep_order(evicted)
    examined_list = dedupe_keep_order(examined)
    skipped = difference(examined_list, evicted_list)
    return {
        "published_path": normalize_path(published_path),
        "evicted": evicted_list,
        "examined": examined_list,
        "evicted_count": len(evicted_list),
        "examined_count": len(examined_list),
        "skipped_count": len(skipped),
    }


def merge_histories(histories) -> list[str]:
    merged: list[str] = []
    for history in histories:
        merged.extend(history)
    return merged


def count_unique(paths) -> int:
    return len({normalize_path(p) for p in paths})


def contains_path(paths, candidate: str) -> bool:
    needle = normalize_path(candidate)
    return any(normalize_path(p) == needle for p in paths)

