from __future__ import annotations

"""Tracks which resources embed which, so a publish can find affected pages.

Each resource declares the paths it embeds directly (``depends_on``). The index
inverts that into a "who embeds me" map. A page that embeds a content fragment
is a *dependent* of that fragment; a fragment that embeds another fragment is a
dependent of the inner one. Because embeds nest, the set of resources affected by
a publish is found by walking the dependent edges, not just reading one level.
"""

from collections import deque

from fragment_models import Resource, normalize_path


class DependencyIndex:
    def __init__(self) -> None:
        # path -> set of paths it embeds directly
        self._depends_on: dict[str, set[str]] = {}
        # path -> set of paths that embed it directly (inverse edges)
        self._dependents: dict[str, set[str]] = {}
        self._kinds: dict[str, str] = {}

    def register(self, resource: Resource) -> None:
        """Record a resource and its direct embeds, refreshing old edges."""

        path = resource.path
        self._kinds[path] = resource.kind
        self._drop_outgoing(path)
        new_edges = {normalize_path(dep) for dep in resource.depends_on}
        self._depends_on[path] = new_edges
        for dep in new_edges:
            self._dependents.setdefault(dep, set()).add(path)

    def _drop_outgoing(self, path: str) -> None:
        for dep in self._depends_on.get(path, set()):
            holders = self._dependents.get(dep)
            if holders:
                holders.discard(path)
        self._depends_on[path] = set()

    def register_all(self, resources) -> None:
        for resource in resources:
            self.register(resource)

    def direct_dependents_of(self, path: str) -> set[str]:
        """Paths that embed ``path`` directly (one hop)."""

        return set(self._dependents.get(normalize_path(path), set()))

    def dependencies_of(self, path: str) -> set[str]:
        """Paths that ``path`` embeds directly."""

        return set(self._depends_on.get(normalize_path(path), set()))

    def transitive_dependents_of(self, path: str) -> set[str]:
        """Every path that embeds ``path`` directly or through other resources.

        Walks the inverse edges outward from ``path``. The starting path itself
        is not included in the result.
        """

        start = normalize_path(path)
        seen: set[str] = set()
        queue: deque[str] = deque(self._dependents.get(start, set()))
        while queue:
            node = queue.popleft()
            if node in seen:
                continue
            seen.add(node)
            for holder in self._dependents.get(node, set()):
                if holder not in seen:
                    queue.append(holder)
        seen.discard(start)
        return seen

    def transitive_dependencies_of(self, path: str) -> set[str]:
        """Every path that ``path`` embeds, directly or transitively."""

        start = normalize_path(path)
        seen: set[str] = set()
        queue: deque[str] = deque(self._depends_on.get(start, set()))
        while queue:
            node = queue.popleft()
            if node in seen:
                continue
            seen.add(node)
            for dep in self._depends_on.get(node, set()):
                if dep not in seen:
                    queue.append(dep)
        seen.discard(start)
        return seen

    def is_dependent(self, candidate: str, resource_path: str) -> bool:
        return normalize_path(candidate) in self.transitive_dependents_of(resource_path)

    def known_paths(self) -> set[str]:
        paths = set(self._depends_on) | set(self._dependents) | set(self._kinds)
        return paths

    def kind_of(self, path: str) -> str | None:
        return self._kinds.get(normalize_path(path))

    def is_known(self, path: str) -> bool:
        return normalize_path(path) in self.known_paths()

    def pages_only(self, paths) -> set[str]:
        return {p for p in paths if self._kinds.get(p) == "page"}

    def dependent_count(self, path: str) -> int:
        return len(self.transitive_dependents_of(path))

    def clear(self) -> None:
        self._depends_on.clear()
        self._dependents.clear()
        self._kinds.clear()

