from __future__ import annotations

"""The publish/serve loop that sits on top of the cache and the index.

A page is rendered once and cached. Later requests for the same path are served
from the cache verbatim. When an author republishes a resource, the dispatcher
invalidates the affected cache entries; the next request for any flushed path
re-renders against the current published content and re-caches the fresh HTML.

Re-rendering is modeled by a per-path version counter: each publish of a path
bumps its version, and the rendered HTML embeds the versions of everything it
contains so that stale embeds are visible in the output.
"""

from cache_invalidator import invalidate
from dependency_index import DependencyIndex
from fragment_models import (
    InvalidationResult,
    PublishEvent,
    RenderedPage,
    Resource,
    normalize_path,
)
from page_cache import PageCache


class Dispatcher:
    def __init__(self, cache: PageCache | None = None, index: DependencyIndex | None = None) -> None:
        self._cache = cache if cache is not None else PageCache()
        self._index = index if index is not None else DependencyIndex()
        self._resources: dict[str, Resource] = {}
        self._versions: dict[str, int] = {}
        self._seq = 0

    @property
    def cache(self) -> PageCache:
        return self._cache

    @property
    def index(self) -> DependencyIndex:
        return self._index

    def register(self, resource: Resource) -> Resource:
        """Make a resource known and bump its version (a publish/activation)."""

        path = resource.path
        self._resources[path] = resource
        self._index.register(resource)
        self._versions[path] = self._versions.get(path, 0) + 1
        return resource

    def register_all(self, resources) -> None:
        for resource in resources:
            self.register(resource)

    def _render(self, path: str) -> RenderedPage:
        """Build HTML for a path, embedding current versions of its embeds."""

        target = normalize_path(path)
        resource = self._resources.get(target)
        own_version = self._versions.get(target, 1)
        if resource is None:
            body = f"[{target}@v{own_version}]"
            return RenderedPage(path=target, html=body, version=own_version)

        parts = [f"{target}@v{own_version}"]
        embedded = self._index.transitive_dependencies_of(target)
        for dep in sorted(embedded):
            parts.append(f"{dep}@v{self._versions.get(dep, 1)}")
        body = "[" + " | ".join(parts) + "]"
        return RenderedPage(path=target, html=body, version=own_version)

    def serve(self, path: str) -> RenderedPage:
        """Return the cached page, rendering and caching on a miss."""

        target = normalize_path(path)
        cached = self._cache.get(target)
        if cached is not None:
            return cached
        rendered = self._render(target)
        self._cache.put(rendered)
        return rendered

    def warm(self, paths) -> None:
        """Pre-render and cache a set of pages."""

        for path in paths:
            self.serve(path)

    def publish(self, path: str, note: str = "") -> InvalidationResult:
        """Activate a resource: bump its version and flush affected pages."""

        target = normalize_path(path)
        if target in self._resources:
            self.register(self._resources[target])
        else:
            self._versions[target] = self._versions.get(target, 0) + 1
        self._seq += 1
        PublishEvent(path=target, sequence=self._seq, note=note)
        return invalidate(self._cache, self._index, target)

    def is_cached(self, path: str) -> bool:
        return self._cache.contains(path)

    def served_html(self, path: str) -> str:
        return self.serve(path).html

    def version_of(self, path: str) -> int:
        return self._versions.get(normalize_path(path), 1)

    def cached_version_of(self, path: str) -> int | None:
        return self._cache.version_of(path)

    def embeds_current_version(self, page_path: str, dep_path: str) -> bool:
        """Whether the served page reflects the dep's current version."""

        dep = normalize_path(dep_path)
        token = f"{dep}@v{self.version_of(dep)}"
        return token in self.served_html(page_path)

    def cached_paths(self) -> list[str]:
        return self._cache.cached_paths()


def build_dispatcher(resources) -> Dispatcher:
    dispatcher = Dispatcher()
    dispatcher.register_all(resources)
    return dispatcher

