        return token in self.served_html(page_path)

    def cached_paths(self) -> list[str]:
        return self._cache.cached_paths()


def build_dispatcher(resources) -> Dispatcher:
    dispatcher = Dispatcher()
    dispatcher.register_all(resources)
    return dispatcher

