        cleaned = tuple(normalize_path(dep) for dep in self.depends_on)
        object.__setattr__(self, "depends_on", cleaned)

    def is_page(self) -> bool:
        return self.kind == "page"


@dataclass(frozen=True)
class RenderedPage:
    """The HTML the dispatcher would hand back for a path, plus its version."""

    path: str
    html: str
    version: int = 1

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", normalize_path(self.path))
        if self.version < 1:
            raise ValueError("version must be positive")

    def with_version(self, version: int) -> "RenderedPage":
        return RenderedPage(path=self.path, html=self.html, version=version)


@dataclass
class PublishEvent:
    """A publish/activation of one resource at a point in logical time."""

    path: str
    sequence: int
    note: str = ""

    def __post_init__(self) -> None:
        self.path = normalize_path(self.path)
        if self.sequence < 0:
            raise ValueError("sequence must be non-negative")


@dataclass
class InvalidationResult:
    """What a single invalidation actually touched."""

    published_path: str
    evicted_paths: tuple[str, ...] = ()
    examined_paths: tuple[str, ...] = ()
    history: list[str] = field(default_factory=list)

    def evicted_count(self) -> int:
        return len(self.evicted_paths)

    def did_evict(self, path: str) -> bool:
        return normalize_path(path) in self.evicted_paths

    def as_dict(self) -> dict[str, object]:
        return {
            "published_path": self.published_path,
            "evicted_paths": list(self.evicted_paths),
            "examined_paths": list(self.examined_paths),
            "evicted_count": self.evicted_count(),
        }


def build_resource(path: str, kind: str = "page", depends_on: list[str] | None = None) -> Resource:
    """Convenience builder used by callers and tests."""

    return Resource(path=path, kind=kind, depends_on=tuple(depends_on or ()))


def page(path: str, depends_on: list[str] | None = None) -> Resource:
    return build_resource(path, kind="page", depends_on=depends_on)


def fragment(path: str, depends_on: list[str] | None = None) -> Resource:
    return build_resource(path, kind="fragment", depends_on=depends_on)


def render(path: str, html: str, version: int = 1) -> RenderedPage:
    return RenderedPage(path=path, html=html, version=version)

