from __future__ import annotations

"""The dispatcher's rendered-page cache, keyed by request path.

This is a plain in-memory store: a request path maps to the ``RenderedPage`` the
dispatcher served for it. Hits are served straight from here without going back
to the publish instance. Eviction is the only way a stale entry leaves; the
invalidation module decides which keys to drop.
"""

from fragment_models import RenderedPage, normalize_path


class PageCache:
    def __init__(self) -> None:
        self._entries: dict[str, RenderedPage] = {}
        self._hits = 0
        self._misses = 0

    def put(self, rendered: RenderedPage) -> RenderedPage:
        self._entries[rendered.path] = rendered
        return rendered

    def get(self, path: str) -> RenderedPage | None:
        key = normalize_path(path)
        entry = self._entries.get(key)
        if entry is None:
            self._misses += 1
        else:
            self._hits += 1
        return entry

    def peek(self, path: str) -> RenderedPage | None:
        """Look up without touching hit/miss counters."""

        return self._entries.get(normalize_path(path))

    def contains(self, path: str) -> bool:
        return normalize_path(path) in self._entries

    def evict(self, path: str) -> bool:
        """Drop one entry. Returns whether something was actually removed."""

        key = normalize_path(path)
        if key in self._entries:
            del self._entries[key]
            return True
        return False

    def evict_many(self, paths) -> int:
        removed = 0
        for path in paths:
            if self.evict(path):
                removed += 1
        return removed

    def cached_paths(self) -> list[str]:
        return list(self._entries)

    def version_of(self, path: str) -> int | None:
        entry = self.peek(path)
        return entry.version if entry is not None else None

    def html_of(self, path: str) -> str | None:
        entry = self.peek(path)
        return entry.html if entry is not None else None

    def size(self) -> int:
        return len(self._entries)

    def is_empty(self) -> bool:
        return not self._entries

    def clear(self) -> None:
        self._entries.clear()

    def snapshot(self) -> dict[str, int]:
        return {path: entry.version for path, entry in self._entries.items()}

    @property
    def hits(self) -> int:
        return self._hits

    @property
    def misses(self) -> int:
        return self._misses

    def reset_stats(self) -> None:
        self._hits = 0
        self._misses = 0

    def hit_ratio(self) -> float:
        total = self._hits + self._misses
        if total == 0:
            return 0.0
        return self._hits / total

    def __contains__(self, path: object) -> bool:
        if not isinstance(path, str):
            return False
        return self.contains(path)

    def __len__(self) -> int:
        return len(self._entries)

